// Interface between the code generated by recomp68k.py and the port that uses it.
#ifndef M68K_RT_H
#define M68K_RT_H
#include <stdint.h>

#define M68K_EXIT 0xFFFFFFFFu   // returned by m68k_external() to leave m68k_run()

typedef struct m68k {
  uint32_t d[8], a[8];          // a[7] is the active stack pointer
  uint32_t pc;                  // where m68k_run() starts
  uint32_t osp;                 // the inactive stack pointer (USP in supervisor mode, SSP in user mode)
  uint32_t x, n, z, v, c;       // flags, 0 or 1
  uint32_t srh;                 // SR bits 15-8: T (bit 7), S (bit 5), interrupt mask (bits 2-0)
  volatile uint32_t ipl;        // interrupt level asked by the hardware (0 = none), set by the port
} m68k_t;

// Runs the translated code from c->pc until m68k_external() returns M68K_EXIT.
void m68k_run(m68k_t *c);

// Called for an address that has no translated code (registers are up to date in *c): the port
// replaces the BIOS there, or reports a missing entry point. Returns the next address, or M68K_EXIT.
uint32_t m68k_external(m68k_t *c, uint32_t pc);

// STOP: waits until c->ipl is above the interrupt mask (the port sleeps with wfi).
void m68k_stop(m68k_t *c);

#ifndef M68K_RESET_DEVICES
#define M68K_RESET_DEVICES(c)
#endif
#endif
